package com.yeyamo_mobile.api.interaction_service.interfaces.rest;import com.yeyamo_mobile.api.interaction_service.application.GenericInteractionService;import com.yeyamo_mobile.api.interaction_service.infrastructure.persistence.GenericInteractionEntity;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1/interactions")public class GenericInteractionController{private final GenericInteractionService service;public GenericInteractionController(GenericInteractionService s){service=s;}public record Request(@Size(max=5000)String body,@Size(max=60)String channel){}
 @PostMapping("/{targetType}/{targetId}/{type}")@ResponseStatus(HttpStatus.CREATED)public GenericInteractionEntity add(@PathVariable GenericInteractionEntity.TargetType targetType,@PathVariable String targetId,@PathVariable GenericInteractionEntity.Type type,@RequestBody(required=false)Request r,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return service.add(targetType,targetId,type,a.getName(),r==null?null:r.body(),r==null?null:r.channel(),c);}
 @DeleteMapping("/{targetType}/{targetId}/{type}")@ResponseStatus(HttpStatus.NO_CONTENT)public void remove(@PathVariable GenericInteractionEntity.TargetType targetType,@PathVariable String targetId,@PathVariable GenericInteractionEntity.Type type,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){service.remove(targetType,targetId,type,a.getName(),c);}
 @GetMapping("/{targetType}/{targetId}/comments")public List<GenericInteractionEntity>comments(@PathVariable GenericInteractionEntity.TargetType targetType,@PathVariable String targetId){return service.comments(targetType,targetId);}}
